class Solution:
    def max_sum(self, nums: list[int], k: int) -> int:
        if not nums or k <= 0:
            return 0
        window_sum = sum(nums[:k])
        max_sum = window_sum
        for i in range(len(nums) - k):
            window_sum += nums[i + k] - nums[i]
            max_sum = max(max_sum, window_sum)
        return max_sum

